"""Offline TLS/HTTP fake; certs are generated by openssl in pytest tmp directories."""
import socket
import ssl
import threading
import time


class FakeTLS:
    def __init__(self, cert, key, *, response=None, socketpair=False, version=None, delay=0, fragment=False, handshake_delay=0,
                 response_factory=None, close_notify=True, byte_delay=0):
        self.context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        self.context.load_cert_chain(cert, key)
        if version:
            self.context.minimum_version = self.context.maximum_version = version
        self.context.set_servername_callback(lambda sock, name, ctx: self.sni.append(name))
        self.response = response or b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\nDate: Mon, 19 Oct 2026 00:00:00 GMT\r\n\r\nOK"
        self.connections, self.requests, self.sni, self.versions, self.errors = 0, [], [], [], []
        self.delay, self.fragment, self.sock, self._stop = delay, fragment, None, False
        self.handshake_delay = handshake_delay
        self.response_factory, self.close_notify, self.byte_delay = response_factory, close_notify, byte_delay
        self._streams = []
        self.port = 443
        if not socketpair:
            self.sock = socket.socket()
            self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.sock.bind(("127.0.0.1", 0)); self.sock.listen(16)
            self.port = self.sock.getsockname()[1]
            threading.Thread(target=self._serve, daemon=True).start()

    def _serve(self):
        while not self._stop:
            try: c, _ = self.sock.accept()
            except OSError: return
            self._start(c)

    def _start(self, c):
        self.connections += 1
        self._streams.append(c)
        threading.Thread(target=self._conn, args=(c,), daemon=True).start()

    def open_stream(self):
        a, b = socket.socketpair()
        self._start(b)
        return a

    def _conn(self, c):
        try:
            c.settimeout(12)
            if self.handshake_delay: time.sleep(self.handshake_delay)
            with self.context.wrap_socket(c, server_side=True) as tls:
                self._streams.append(tls)
                self.versions.append(tls.version())
                data = b""
                while b"\r\n\r\n" not in data:
                    d = tls.recv(4096)
                    if not d: return
                    data += d
                    if len(data) > 16384: return
                head, body = data.split(b"\r\n\r\n", 1)
                length = next((int(x.split(b":", 1)[1]) for x in head.split(b"\r\n")[1:]
                               if x.lower().startswith(b"content-length:")), 0)
                while len(body) < length:
                    d = tls.recv(4096)
                    if not d: return
                    body += d
                self.requests.append((head, body))
                if self.delay: time.sleep(self.delay)
                response = self.response_factory(head, body) if self.response_factory else self.response
                if self.fragment or self.byte_delay:
                    for b in response:
                        tls.sendall(bytes([b]))
                        if self.byte_delay: time.sleep(self.byte_delay)
                else: tls.sendall(response)
                # Send close_notify so until-close framing also has an authenticated EOF.
                if self.close_notify:
                    try: tls.unwrap().close()
                    except (ssl.SSLError, OSError): pass
        except (ssl.SSLError, OSError) as error:
            self.errors.append(str(error))
        finally:
            c.close()

    def close(self):
        self._stop = True
        if self.sock: self.sock.close()
        for s in self._streams:
            try: s.close()
            except OSError: pass

    def __enter__(self): return self
    def __exit__(self, *args): self.close()
